import React, { useMemo, useState } from 'react'
import { AnimatePresence, motion, useReducedMotion } from 'framer-motion'
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { Activity, ArrowDownRight, ArrowLeft, ArrowRight, ArrowUpRight, Bell, Building2, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, CircleAlert, CircleDollarSign, CircleHelp, ClipboardList, Clock3, CreditCard, Download, Eye, EyeOff, FileBarChart, FileText, Filter, Gauge, Home, Layers3, LayoutDashboard, Leaf, Lightbulb, LockKeyhole, LogOut, MapPin, Menu, MoreHorizontal, Plus, RadioTower, RefreshCw, Search, Settings, Shield, SlidersHorizontal, Sparkles, Trash2, UserRound, Users, Wallet, Wifi, Wrench, X, Zap, type LucideIcon } from 'lucide-react'
import { activities, collectionData, consumptionData, type Bill, type Consumer, type Meter, type Technician } from './data'
import { db, demoMode, signIn } from './services'

type Page='Dashboard'|'Consumers'|'Meters'|'Bills'|'Technicians'|'Reports'|'Settings'
type Notice={id:number;text:string;kind?:'success'|'error'}
type Modal={type:'consumer'|'technician'|'bill'|'meter'|'delete'|'details';id?:string}
const pageIcons:Record<Page,LucideIcon>={Dashboard:LayoutDashboard,Consumers:Users,Meters:Gauge,Bills:FileText,Technicians:Wrench,Reports:FileBarChart,Settings}
const pieData=[{name:'Residential',value:58,color:'#4664f5'},{name:'Business',value:27,color:'#34b1d6'},{name:'Commercial',value:15,color:'#99decf'}]
const money=(n:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n)

function Brand({light=false}:{light?:boolean}){return <div className={`brand ${light?'brand-light':''}`}><span className="brand-symbol"><i/><i/><i/><i/></span><span>gridflow</span></div>}
function Pill({children,tone='gray',dot=false}:{children:React.ReactNode;tone?:string;dot?:boolean}){return <span className={`pill pill-${tone}`}>{dot&&<i/>}{children}</span>}
function IconButton({icon:I,label,onClick}:{icon:LucideIcon;label:string;onClick?:()=>void}){return <button className="icon-button" aria-label={label} title={label} onClick={onClick}><I size={17}/></button>}
function Toasts({items,dismiss}:{items:Notice[];dismiss:(id:number)=>void}){return <div className="toast-stack" aria-live="polite">{items.map(n=><motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} exit={{opacity:0,y:8}} key={n.id} className={`toast toast-${n.kind||'success'}`}><CheckCircle2 size={17}/>{n.text}<button onClick={()=>dismiss(n.id)} aria-label="Dismiss"><X size={15}/></button></motion.div>)}</div>}

export default function App(){
 const [page,setPage]=useState<Page>('Dashboard'),[dashboard,setDashboard]=useState(false),[login,setLogin]=useState(false),[menu,setMenu]=useState(false),[search,setSearch]=useState(''),[query,setQuery]=useState(''),[notices,setNotices]=useState<Notice[]>([]),[modal,setModal]=useState<Modal|null>(null),[selected,setSelected]=useState<string|null>(null),[profileMenu,setProfileMenu]=useState(false),[notif,setNotif]=useState(false),[dateRange,setDateRange]=useState('Last 30 days'),[chartFilter,setChartFilter]=useState('This year'),[activityFilter,setActivityFilter]=useState(false)
 const reduced=useReducedMotion()
 const [consumers,setConsumers]=useState<Consumer[]>(db.consumers),[meters,setMeters]=useState<Meter[]>(db.meters),[bills,setBills]=useState<Bill[]>(db.bills),[technicians,setTechnicians]=useState<Technician[]>(db.technicians)
 const notify=(text:string,kind:'success'|'error'='success')=>{const id=Date.now()+Math.random();setNotices(a=>[...a,{id,text,kind}]);window.setTimeout(()=>setNotices(a=>a.filter(n=>n.id!==id)),3800)}
 const update=(key:'consumers'|'meters'|'bills'|'technicians',items:Consumer[]|Meter[]|Bill[]|Technician[])=>{if(key==='consumers'){setConsumers(items as Consumer[]);db.consumers=items as Consumer[]}if(key==='meters'){setMeters(items as Meter[]);db.meters=items as Meter[]}if(key==='bills'){setBills(items as Bill[]);db.bills=items as Bill[]}if(key==='technicians'){setTechnicians(items as Technician[]);db.technicians=items as Technician[]}db.persist(key)}
 const go=(p:Page)=>{setPage(p);setDashboard(true);setLogin(false);setMenu(false);setSearch('');setSelected(null);window.scrollTo({top:0,behavior:'smooth'})}
 const openDashboard=()=>{setPage('Dashboard');setDashboard(true);setLogin(false);setMenu(false);window.scrollTo({top:0,behavior:'smooth'})}
 const openLogin=()=>{setLogin(true);setDashboard(false);window.scrollTo({top:0,behavior:'smooth'})}
 const filtered=useMemo(()=>consumers.filter(c=>`${c.name} ${c.account} ${c.address} ${c.zone} ${c.plan}`.toLowerCase().includes(query.toLowerCase())),[consumers,query])
 const active=consumers.filter(c=>c.status==='Active').length,paid=bills.filter(b=>b.status==='Paid').reduce((a,b)=>a+b.amount,0)
 return <>
  {!dashboard&&!login?<Landing openDashboard={openDashboard} openLogin={openLogin} go={go}/>:login?<Login onBack={openDashboard} onSignIn={async(u,p)=>{const r=await signIn(u,p);if(r.ok){if(r.demo)localStorage.setItem('gridflow:demo-session','true');notify(r.demo?'Demo session started.':'Signed in successfully.');openDashboard()}else notify(r.message||'Sign-in failed. Check your credentials.','error')}} demoMode={demoMode}/>:<div className="app-shell">
   <aside className={`sidebar ${menu?'sidebar-open':''}`}><div className="sidebar-brand"><Brand/><button className="sidebar-collapse" aria-label="Collapse sidebar">⌃⌄</button></div><div className="workspace-switcher"><span className="workspace-mark">N</span><span className="workspace-copy"><b>Northstar Energy</b><small>Organization</small></span><ChevronDown size={15}/></div>
    <div className="side-label">WORKSPACE</div><nav className="side-nav" aria-label="Main navigation">{(['Dashboard','Consumers','Meters','Bills','Technicians','Reports'] as Page[]).map(item=>{const I=pageIcons[item];return <button key={item} className={`side-link ${page===item?'selected':''}`} onClick={()=>go(item)}><I size={18}/><span>{item}</span>{item==='Bills'&&<span className="nav-count">3</span>}</button>})}</nav>
    <div className="side-label side-label-tools">PREFERENCES</div><nav className="side-nav"><button className={`side-link ${page==='Settings'?'selected':''}`} onClick={()=>go('Settings')}><Settings size={18}/><span>Settings</span></button><button className="side-link" onClick={()=>notify('Help center is ready to connect.')}><CircleHelp size={18}/><span>Help center</span></button></nav>
    <div className="sidebar-bottom"><div className="sync-card"><div className="sync-card-top"><span className="sync-orb"><RefreshCw size={14}/></span><b>System healthy</b><i className="live-dot"/></div><p>All systems are operational and data is up to date.</p><div className="sync-track"><i/></div><div className="sync-foot"><span>Last sync</span><b>Just now</b></div></div><div className="sidebar-user"><div className="avatar avatar-user">AR</div><div className="sidebar-user-copy"><b>Alex Rivera</b><small>Administrator</small></div><button className="user-more" onClick={()=>setProfileMenu(!profileMenu)} aria-label="Profile options"><MoreHorizontal size={17}/></button>{profileMenu&&<div className="profile-pop"><button onClick={()=>{setProfileMenu(false);go('Settings')}}><UserRound size={15}/> Profile settings</button><button onClick={()=>{setProfileMenu(false);openLogin()}}><LogOut size={15}/> Sign out</button></div>}</div></div>
   </aside>{menu&&<button className="mobile-scrim" aria-label="Close menu" onClick={()=>setMenu(false)}/>}
   <main className="main-area"><header className="topbar"><div className="topbar-left"><button className="mobile-menu icon-button" aria-label="Open navigation" onClick={()=>setMenu(true)}><Menu size={18}/></button><div className="breadcrumbs"><span>Workspace</span><ChevronRight size={14}/><b>{page}</b></div></div><div className="topbar-actions"><label className="global-search"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search anything..."/><kbd>⌘ K</kbd></label><span className="topbar-divider"/><button className="period-button" onClick={()=>setDateRange(dateRange==='Last 30 days'?'Last 7 days':'Last 30 days')}><CalendarDays size={15}/>{dateRange}<ChevronDown size={14}/></button><div className="notification-wrap"><IconButton icon={Bell} label="Notifications" onClick={()=>setNotif(!notif)}/><i className="notification-indicator"/>{notif&&<div className="notification-pop"><b>Notifications</b><p><CheckCircle2/> Sync complete · just now</p><p><CreditCard/> 3 bills are awaiting payment</p><p><Gauge/> 5,281 meter readings today</p><button onClick={()=>setNotif(false)}>Mark all as read</button></div>}</div><div className="avatar avatar-user top-avatar">AR</div></div></header>
    <div className="page-content"><AnimatePresence mode="wait"><motion.div key={page} initial={{opacity:0,y:reduced?0:8}} animate={{opacity:1,y:0}} exit={{opacity:0,y:reduced?0:-5}} transition={{duration:.2}}>
     {page==='Dashboard'&&<DashboardPage consumers={consumers} meters={meters} bills={bills} technicians={technicians} active={active} paid={paid} go={go} chartFilter={chartFilter} setChartFilter={setChartFilter} setQuery={setQuery} activityFilter={activityFilter} setActivityFilter={setActivityFilter}/>}
     {page==='Consumers'&&<ConsumersPage rows={filtered} query={query} setQuery={setQuery} add={()=>{setSelected(null);setModal({type:'consumer'})}} edit={id=>{setSelected(id);setModal({type:'consumer',id})}} del={id=>setModal({type:'delete',id})} view={id=>setModal({type:'details',id})}/>}
     {page==='Meters'&&<MetersPage rows={meters} add={()=>setModal({type:'meter'})} edit={id=>setModal({type:'meter',id})}/>}
     {page==='Bills'&&<BillsPage rows={bills} generate={()=>setModal({type:'bill'})} exportData={()=>exportRows(bills,'gridflow-bills.csv')}/>}
     {page==='Technicians'&&<TechniciansPage rows={technicians} add={()=>setModal({type:'technician'})} edit={id=>{setSelected(id);setModal({type:'technician',id})}}/>}
     {page==='Reports'&&<ReportsPage consumers={consumers} bills={bills} meters={meters} exportData={()=>exportRows(bills,'gridflow-report.csv')}/>}
     {page==='Settings'&&<SettingsPage demoMode={demoMode} notify={notify}/>}
    </motion.div></AnimatePresence></div></main></div>}
  <AnimatePresence>{modal&&<EntityModal modal={modal} close={()=>setModal(null)} consumers={consumers} meters={meters} bills={bills} technicians={technicians} update={update} notify={notify}/>}</AnimatePresence><Toasts items={notices} dismiss={id=>setNotices(n=>n.filter(x=>x.id!==id))}/>
 </>
}

function Landing({openDashboard,openLogin,go}:{openDashboard:()=>void;openLogin:()=>void;go:(p:Page)=>void}){
 const [mobile,setMobile]=useState(false),[scrolled,setScrolled]=useState(false)
 React.useEffect(()=>{const f=()=>setScrolled(window.scrollY>90);window.addEventListener('scroll',f,{passive:true});return()=>window.removeEventListener('scroll',f)},[])
 return <div className="landing"><section className="hero" id="overview"><video className="hero-video" autoPlay loop muted playsInline preload="metadata" aria-hidden="true"><source src="/videos/gemini-loop.webm" type="video/webm"/></video><div className="hero-shade"/><div className={`site-nav ${scrolled?'site-nav-scrolled':''}`}><button className="landing-brand-button" onClick={()=>window.scrollTo({top:0,behavior:'smooth'})}><Brand light/></button><div className={`site-nav-links ${mobile?'nav-mobile-open':''}`}><a href="#overview" onClick={()=>setMobile(false)}>Overview</a><a href="#platform" onClick={()=>setMobile(false)}>Platform</a><a href="#analytics" onClick={()=>setMobile(false)}>Analytics</a><a href="#features" onClick={()=>setMobile(false)}>Features</a><button className="nav-login" onClick={openLogin}>Log in <ArrowUpRight size={15}/></button></div><button className="nav-mobile-toggle" aria-label="Toggle navigation" onClick={()=>setMobile(!mobile)}>{mobile?<X size={21}/>:<Menu size={21}/>}</button></div>
  <div className="hero-content"><div className="hero-copy"><motion.div initial={{opacity:0,y:10}} animate={{opacity:1,y:0}} className="eyebrow hero-eyebrow"><span className="eyebrow-line"/> ENERGY OPERATIONS, IN SYNC</motion.div><motion.h1 initial={{opacity:0,y:18}} animate={{opacity:1,y:0}} transition={{duration:.65,delay:.08}}>Powering transparent<br/>energy <em>management.</em></motion.h1><motion.p initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:.17}}>Monitor consumers, manage smart meters, automate billing, and see your network’s performance in real time.</motion.p><div className="hero-ctas"><button className="button-primary hero-primary" onClick={openDashboard}>Access dashboard <ArrowRight size={17}/></button><a className="hero-secondary" href="#analytics">Explore analytics <ArrowDownRight size={16}/></a></div><div className="hero-proof"><div className="proof-avatars"><span>AR</span><span>ML</span><span>JT</span><span>+</span></div><div><div className="proof-stars">★★★★★</div><span>Trusted by energy teams everywhere</span></div></div></div><div className="hero-aside"><div className="hero-live-pill"><i className="live-dot"/> LIVE GRID STATUS <span>·</span> OPTIMAL</div><div className="hero-aside-bottom"><span className="mini-wave"><Wifi size={16}/></span><span>Every connection.<br/>In perfect sync.</span><ArrowUpRight size={16}/></div></div></div>
  <div className="hero-bottom"><span className="hero-coordinate">37°46'49.3"N&nbsp; 122°25'09.7"W</span><span className="hero-scroll">SCROLL TO EXPLORE <i/></span><span className="hero-edition">GRIDFLOW PLATFORM <b>01 — 06</b></span></div>
  <div className="hero-stats">{[{label:'Consumers connected',value:'1,248',icon:Users},{label:'Units tracked',value:'24,781',icon:Zap},{label:'Collection rate',value:'98.7%',icon:CircleDollarSign},{label:'Field technicians',value:'32',icon:Wrench}].map((s,i)=><motion.div initial={{opacity:0,y:16}} animate={{opacity:1,y:0}} transition={{delay:.25+i*.08}} key={s.label} className="hero-stat"><span className="hero-stat-icon"><s.icon size={17}/></span><div><b>{s.value}</b><span>{s.label}</span></div><ArrowUpRight className="hero-stat-arrow" size={15}/></motion.div>)}</div>
 </section>
 <section className="landing-analytics" id="analytics"><div className="analytics-watermark">GRIDFLOW</div><div className="landing-section-wrap"><div className="analytics-intro"><div className="eyebrow light-eyebrow"><span/> BUILT FOR WHAT’S NEXT</div><h2>When the grid gets<br/>smarter, <em>everyone wins.</em></h2><p>One clear view of your entire operation. From the first meter reading to the final payment.</p><button className="button-primary dashboard-cta" onClick={openDashboard}>Step inside GridFlow <ArrowUpRight size={17}/></button><div className="intro-footnote"><i className="green-pulse"/> LIVE SAMPLE DATA <i/> REFRESHED JUST NOW</div></div>
  <div className="floating-stats-card"><div className="floating-card-header"><div><span className="floating-label">SYSTEM OVERVIEW</span><b>Network pulse</b></div><span className="connection-pill"><i/> ALL SYSTEMS NORMAL</span></div><div className="floating-total"><b>24,781</b><span>kWh <i>↑ 12.8%</i></span></div><div className="floating-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={consumptionData}><defs><linearGradient id="floatArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#5694ff" stopOpacity={.3}/><stop offset="100%" stopColor="#5694ff" stopOpacity={0}/></linearGradient></defs><Area type="monotone" dataKey="usage" stroke="#67a5ff" strokeWidth={2} fill="url(#floatArea)"/><XAxis dataKey="month" tick={false} axisLine={false} tickLine={false}/></AreaChart></ResponsiveContainer></div><div className="floating-card-foot"><span><i className="legend-blue"/> THIS MONTH</span><span>UPDATED 09:41:08 <RefreshCw size={12}/></span></div><div className="floating-live-callout"><div className="callout-icon"><Zap size={17}/></div><span><b>Grid operating at 99.98%</b><small>Real-time system uptime</small></span><Activity size={23} className="callout-wave"/></div></div>
  <div className="energy-node node-a"><span><Zap size={14}/></span></div><div className="energy-node node-b"><span><RadioTower size={14}/></span></div><div className="energy-node node-c"><span><Home size={14}/></span></div><div className="energy-caption caption-a">SMART INFRASTRUCTURE <span>↗ 24,781 UNITS</span></div><div className="energy-caption caption-b">REAL-TIME NETWORK <span>● ONLINE</span></div></div>
  <div className="landing-below-metrics">{[{label:'Smart meters online',value:'99.2%',trend:'+0.8%',icon:Gauge,color:'cyan'},{label:'Energy delivered',value:'18.4 GWh',trend:'+12.4%',icon:Zap,color:'blue'},{label:'Carbon avoided',value:'264 t',trend:'+6.2%',icon:Leaf,color:'green'}].map(v=><div key={v.label} className="below-metric"><span className={`below-metric-icon ${v.color}`}><v.icon size={17}/></span><div><small>{v.label}</small><b>{v.value}</b></div><span className="metric-trend">↗ {v.trend}</span></div>)}</div>
 </section>
 <section id="platform" className="platform-section"><div className="section-heading"><div><div className="eyebrow section-eyebrow"><span/> MADE FOR THE MODERN GRID</div><h2>Complex systems.<br/><em>Clear decisions.</em></h2></div><p>All the moving parts of your energy operation, working together beautifully.</p></div><div className="platform-grid"><FeatureCard icon={Users} tag="01 / CUSTOMERS" title={<>Every customer,<br/>in their right place.</>} copy="A clearer picture of your people, their plans, and the power they use." color="blue" onClick={()=>go('Consumers')}/><FeatureCard icon={Gauge} tag="02 / METERING" title={<>Know what’s happening.<br/>As it happens.</>} copy="Live meter intelligence that helps your entire network run smarter." color="cyan" onClick={()=>go('Meters')}/><FeatureCard icon={CreditCard} tag="03 / BILLING" title={<>Billing that just<br/>makes sense.</>} copy="From accurate usage to on-time payment. Every detail in sync." color="violet" onClick={()=>go('Bills')}/><FeatureCard icon={Wrench} tag="04 / FIELD OPS" title={<>Your team, always<br/>one step ahead.</>} copy="Better visibility for the people keeping your infrastructure running." color="green" onClick={()=>go('Technicians')}/></div></section>
 <section id="features" className="platform-detail"><div className="detail-art"><div className="orbit orbit-1"/><div className="orbit orbit-2"/><div className="orbit orbit-3"/><div className="detail-core"><Brand/><span className="core-halo"><Zap size={26}/></span><span className="core-label">THE GRIDFLOW NETWORK</span></div><div className="detail-orb orb-one"><Home size={16}/></div><div className="detail-orb orb-two"><Gauge size={16}/></div><div className="detail-orb orb-three"><Lightbulb size={16}/></div><div className="detail-orb orb-four"><RadioTower size={16}/></div><span className="detail-orbit-label ol-one">SMART HOMES</span><span className="detail-orbit-label ol-two">LIVE METERING</span><span className="detail-orbit-label ol-three">INTELLIGENCE</span></div><div className="detail-copy"><div className="eyebrow section-eyebrow"><span/> A MORE CONNECTED FUTURE</div><h2>The grid isn’t<br/>going to wait.<br/><em>Now you don’t have to.</em></h2><p>Bring the whole picture into focus. GridFlow connects the people, data, and systems that keep your energy network moving forward.</p><div className="detail-points"><span><Check size={15}/>One view across every operation</span><span><Check size={15}/>Information as it happens</span><span><Check size={15}/>Made to grow with your network</span></div><button className="button-dark" onClick={openDashboard}>Explore the platform <ArrowRight size={17}/></button></div></section>
 <section className="closing-cta"><div className="closing-light"/><div className="eyebrow"><span/> YOUR GRID, REIMAGINED</div><h2>A clearer way<br/>to keep <em>everything moving.</em></h2><p>Bring your entire energy operation into focus.</p><button className="button-white" onClick={openDashboard}>Enter GridFlow <ArrowRight size={17}/></button><span className="closing-deco">G</span></section>
 <footer className="landing-footer"><Brand/><span>© 2026 GridFlow Technologies</span><div><a href="#overview">Privacy</a><a href="#overview">Terms</a><a href="#overview">Status <i className="footer-status"/></a></div><span>BUILT FOR A BRIGHTER GRID <i>✳</i></span></footer></div>
}

function FeatureCard({icon:Icon,tag,title,copy,color,onClick}:{icon:LucideIcon;tag:string;title:React.ReactNode;copy:string;color:string;onClick:()=>void}){return <button className={`feature-card feature-${color}`} onClick={onClick}><div className="feature-head"><span className="feature-icon"><Icon size={20}/></span><ArrowUpRight size={17}/></div><span className="feature-tag">{tag}</span><h3>{title}</h3><p>{copy}</p><span className="feature-line"/></button>}

function Login({onBack,onSignIn,demoMode}:{onBack:()=>void;onSignIn:(u:string,p:string)=>void;demoMode:boolean}){
 const [user,setUser]=useState('admin@gridflow.demo'),[pass,setPass]=useState(''),[show,setShow]=useState(false),[error,setError]=useState(''),[busy,setBusy]=useState(false)
 const submit=async(e:React.FormEvent)=>{e.preventDefault();if(!user.trim()||!pass.trim()){setError('Enter a username and password to continue.');return}setBusy(true);setError('');try{await onSignIn(user,pass)}finally{setBusy(false)}}
 return <div className="login-screen"><video className="hero-video login-video" autoPlay loop muted playsInline><source src="/videos/gemini-loop.webm" type="video/webm"/></video><div className="login-overlay"/><button className="login-back" onClick={onBack}><ArrowLeft size={17}/> Back to overview</button><div className="login-center"><div className="login-brand"><Brand light/></div><div className="login-card"><div className="login-logo"><Zap size={21}/></div><div className="login-eyebrow">SECURE ACCESS PORTAL</div><h1>Welcome<br/>back.</h1><p className="login-sub">Your energy operation, right where you left it.</p>{demoMode&&<div className="demo-login-note"><Sparkles size={14}/> Demo mode · no account required</div>}<form onSubmit={submit}><label htmlFor="login-user">Username</label><div className="login-input-wrap"><UserRound size={17}/><input id="login-user" type="email" autoComplete="username" value={user} onChange={e=>setUser(e.target.value)} placeholder="you@company.com"/></div><label htmlFor="login-pass">Password</label><div className="login-input-wrap"><LockKeyhole size={17}/><input id="login-pass" type={show?'text':'password'} autoComplete="current-password" value={pass} onChange={e=>setPass(e.target.value)} placeholder="Enter your password"/><button type="button" aria-label={show?'Hide password':'Show password'} onClick={()=>setShow(!show)}>{show?<EyeOff size={16}/>:<Eye size={16}/>}</button></div>{error&&<div className="login-error"><CircleAlert size={14}/>{error}</div>}<button className="button-primary login-submit" disabled={busy}>{busy?'Connecting…':'Access control center'}<ArrowRight size={17}/></button></form><div className="login-divider"><span/> OR <span/></div><button className="demo-button" onClick={()=>onSignIn('admin@gridflow.demo','demo')}><Sparkles size={16}/>Continue with demo access<ArrowUpRight size={15}/></button><div className="login-foot"><Shield size={13}/> SECURE CONNECTION <i/><span className="live-dot"/> SYSTEM ONLINE</div></div><span className="login-copyright">© 2026 GridFlow Technologies</span></div><div className="login-side-caption"><i/> POWERING A CLEARER FUTURE <span>37°46'49.3"N · 122°25'09.7"W</span></div></div>
}

function SectionHeading({eyebrow,title,subtitle,action}:{eyebrow:string;title:string;subtitle:string;action?:React.ReactNode}){return <div className="section-title-row"><div><div className="eyebrow page-eyebrow"><span/>{eyebrow}</div><h1>{title}</h1><p>{subtitle}</p></div>{action}</div>}
function SelectControl({value,onChange,options}:{value:string;onChange:(v:string)=>void;options:string[]}){return <label className="select-wrap"><select value={value} onChange={e=>onChange(e.target.value)}>{options.map(o=><option key={o}>{o}</option>)}</select><ChevronDown size={14}/></label>}
function DashboardPage({consumers,meters,bills,technicians,active,paid,go,chartFilter,setChartFilter,setQuery,activityFilter,setActivityFilter}:{consumers:Consumer[];meters:Meter[];bills:Bill[];technicians:Technician[];active:number;paid:number;go:(p:Page)=>void;chartFilter:string;setChartFilter:(v:string)=>void;setQuery:(v:string)=>void;activityFilter:boolean;setActivityFilter:(v:boolean)=>void}){
 const online=meters.filter(m=>m.status==='Online').length,collection=Math.round(100*bills.filter(b=>b.status==='Paid').length/Math.max(1,bills.length))
 return <div className="dashboard-page"><SectionHeading eyebrow="SUNDAY, OCTOBER 4, 2026" title="Good morning, Alex" subtitle="Here’s what’s happening across your energy network today." action={<div className="title-actions"><span className="data-mode-pill"><i/> DEMO DATA</span><button className="button-outline" onClick={()=>window.print()}><Download size={15}/> Export overview</button></div>}/>
  <div className="welcome-banner"><div className="welcome-glow"/><span className="welcome-icon"><Zap size={20}/></span><div><b>Your network is running smoothly.</b><p>All systems are operational — last full sync completed moments ago.</p></div><span className="banner-status"><i/> SYSTEMS NOMINAL</span><ArrowUpRight className="welcome-arrow" size={18}/></div>
   <div className="stats-grid">{[{label:'Total consumers',value:consumers.length===8?'1,248':consumers.length.toLocaleString(),delta:'+8.2%',icon:Users,sub:`${consumers.length===8?'1,210':active} active accounts`,color:'blue'},{label:'Energy consumed',value:'24,781',unit:'kWh',delta:'+12.8%',icon:Zap,sub:'Across all connected meters',color:'cyan'},{label:'Collection rate',value:`${consumers.length===8?'98.7':collection}%`,delta:'+2.4%',icon:Wallet,sub:`${money(paid)} collected this month`,color:'green'},{label:'Active technicians',value:'32',delta:'8 on duty',icon:Wrench,sub:`${technicians.length} currently assigned`,color:'violet'}].map(s=><div className="stat-card" key={s.label}><div className="stat-card-top"><span>{s.label}</span><span className={`stat-icon ${s.color}`}><s.icon size={18}/></span></div><div className="stat-value">{s.value}<small>{s.unit}</small></div><div className="stat-card-bottom"><span className="stat-delta">↗ {s.delta}</span><span>{s.sub}</span></div><div className={`stat-spark ${s.color}`}><span/></div></div>)}</div>
  <div className="dashboard-main-grid"><div className="panel consumption-panel"><div className="panel-head"><div><h3>Energy consumption</h3><p>Monthly energy usage across the network</p></div><SelectControl value={chartFilter} onChange={setChartFilter} options={['This year','Last 12 months','This quarter']}/></div><div className="chart-key"><span><i className="key-current"/> This year</span><span><i className="key-last"/> Last year</span><span className="chart-measure">MWh</span></div><div className="consumption-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={consumptionData} margin={{top:12,right:10,left:-12,bottom:0}}><defs><linearGradient id="usageFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#5572f5" stopOpacity={.19}/><stop offset="95%" stopColor="#5572f5" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#eef0f5" strokeDasharray="3 4" vertical={false}/><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fill:'#949aaa',fontSize:11}} dy={8}/><YAxis axisLine={false} tickLine={false} tick={{fill:'#949aaa',fontSize:11}} domain={[0,40]} ticks={[0,10,20,30,40]}/><Tooltip contentStyle={{border:'1px solid #edf0f4',borderRadius:10,fontSize:12,boxShadow:'0 8px 25px rgba(20,25,50,.08)'}} formatter={(v)=>[`${v} MWh`,'Usage']}/><Area type="monotone" dataKey="last" stroke="#cbd1df" strokeWidth={1.7} strokeDasharray="5 5" fill="none"/><Area type="monotone" dataKey="usage" stroke="#5572f5" strokeWidth={2.5} fill="url(#usageFill)" activeDot={{r:5,fill:'#5572f5',stroke:'white',strokeWidth:3}}/></AreaChart></ResponsiveContainer></div><div className="chart-bottom"><span><i className="green-pulse"/> Readings syncing live</span><span>LAST UPDATED 09:41 AM <RefreshCw size={12}/></span></div></div>
   <div className="panel distribution-panel"><div className="panel-head"><div><h3>Consumer distribution</h3><p>Accounts by service type</p></div><button className="plain-icon" aria-label="More options"><MoreHorizontal size={18}/></button></div><div className="distribution-chart"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={pieData} dataKey="value" nameKey="name" cx="50%" cy="50%" innerRadius="68%" outerRadius="91%" paddingAngle={4} stroke="none" startAngle={90} endAngle={-270}>{pieData.map(d=><Cell key={d.name} fill={d.color}/>)}</Pie><Tooltip formatter={(v)=>[`${v}%`,'Accounts']}/></PieChart></ResponsiveContainer><div className="donut-center"><b>{consumers.length===8?'1,248':consumers.length.toLocaleString()}</b><span>CONSUMERS</span></div></div><div className="distribution-legend">{pieData.map(d=><div key={d.name}><i style={{background:d.color}}/><span>{d.name}</span><b>{d.value}%</b></div>)}</div><button className="panel-link" onClick={()=>go('Consumers')}>View all consumers <ArrowRight size={15}/></button></div>
  </div>
  <div className="dashboard-lower-grid"><div className="panel collection-panel"><div className="panel-head"><div><h3>Bill collection</h3><p>Payment performance by month</p></div><button className="panel-link compact" onClick={()=>go('Bills')}>All bills <ArrowRight size={14}/></button></div><div className="collection-summary"><b>$48,294</b><span className="stat-delta">↗ 6.8%</span><small>collected this month</small></div><div className="bar-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={collectionData} margin={{top:6,right:5,left:-28,bottom:0}} barCategoryGap="28%"><CartesianGrid stroke="#eff1f5" vertical={false} strokeDasharray="3 4"/><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fill:'#9298a8',fontSize:10}} dy={7}/><YAxis axisLine={false} tickLine={false} tick={{fill:'#9298a8',fontSize:10}} ticks={[0,50,100]} tickFormatter={v=>`${v}%`}/><Tooltip cursor={{fill:'#f7f8fa'}} formatter={v=>[`${v}%`,'Bills']}/><Bar dataKey="paid" fill="#5370f4" radius={[4,4,0,0]}/></BarChart></ResponsiveContainer></div></div>
   <div className="panel activity-panel"><div className="panel-head"><div><h3>Live activity</h3><p>Recent updates across your network</p></div><button className={`plain-icon ${activityFilter?'filter-active':''}`} aria-label="Filter activity" onClick={()=>setActivityFilter(!activityFilter)}><Filter size={16}/></button></div>{activityFilter&&<div className="activity-filter-note">Showing all recent events <button onClick={()=>setActivityFilter(false)}>Clear</button></div>}<div className="activity-list">{activities.filter((_,i)=>!activityFilter||i<3).map((a,i)=><div className="activity-item" key={a.title}><span className={`activity-icon activity-${a.tone}`}>{a.icon==='check'?<Check size={15}/>:a.icon==='meter'?<Gauge size={15}/>:a.icon==='user'?<Users size={15}/>:<CreditCard size={15}/>}</span><div><b>{a.title}</b><small>{a.detail}</small></div><span className="activity-time">{a.time}</span>{i<activities.length-1&&<i className="activity-line"/>}</div>)}</div><button className="panel-link" onClick={()=>go('Reports')}>View activity log <ArrowRight size={15}/></button></div>
  </div>
  <div className="dashboard-bottom-line"><span><i className="live-dot"/> All services operational</span><span><RefreshCw size={12}/> Last synchronization 09:41:08 AM</span><span><span className="tiny-shield"><Shield size={12}/></span> Demo mode · data saved locally</span></div>
 </div>
}

function SearchControl({value,onChange,placeholder='Search...'}:{value:string;onChange:(v:string)=>void;placeholder?:string}){return <label className="table-search"><Search size={15}/><input value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/></label>}
function PageToolbar({children}:{children:React.ReactNode}){return <div className="page-toolbar">{children}</div>}
function ConsumersPage({rows,query,setQuery,add,edit,del,view}:{rows:Consumer[];query:string;setQuery:(v:string)=>void;add:()=>void;edit:(id:string)=>void;del:(id:string)=>void;view:(id:string)=>void}){
 const [status,setStatus]=useState('All statuses'),[sort,setSort]=useState('Newest first')
 const visible=rows.filter(c=>status==='All statuses'||c.status===status).slice().sort((a,b)=>sort==='Name A–Z'?a.name.localeCompare(b.name):sort==='Highest usage'?b.usage-a.usage:0)
 return <div className="entity-page"><SectionHeading eyebrow="CUSTOMER OPERATIONS" title="Consumers" subtitle="Manage every connection, account, and customer relationship." action={<button className="button-primary" onClick={add}><Plus size={16}/> Add consumer</button>}/><div className="entity-summary-strip"><div><span className="summary-icon blue"><Users size={17}/></span><span><small>Total consumers</small><b>1,248</b></span><i className="summary-trend">↗ 8.2%</i></div><div><span className="summary-icon green"><Check size={17}/></span><span><small>Active accounts</small><b>1,210</b></span></div><div><span className="summary-icon amber"><Clock3 size={17}/></span><span><small>Awaiting activation</small><b>24</b></span></div><div><span className="summary-icon violet"><MapPin size={17}/></span><span><small>Service zones</small><b>8</b></span></div></div><div className="panel table-panel"><PageToolbar><SearchControl value={query} onChange={setQuery} placeholder="Find by name, account, address..."/><SelectControl value={status} onChange={setStatus} options={['All statuses','Active','Pending','Suspended']}/><SelectControl value={sort} onChange={setSort} options={['Newest first','Name A–Z','Highest usage']}/><button className="button-outline" onClick={()=>exportRows(visible,'gridflow-consumers.csv')}><Download size={15}/> Export</button></PageToolbar><DataTable headers={['CONSUMER','ACCOUNT ID','SERVICE ADDRESS','PLAN','USAGE (KWH)','STATUS','']}>
 {visible.map(c=><tr key={c.id} onDoubleClick={()=>view(c.id)}><td><button className="table-person" onClick={()=>view(c.id)}><span className={`avatar avatar-${c.id.charCodeAt(2)%5}`}>{c.name.split(' ').map(x=>x[0]).join('')}</span><b>{c.name}</b></button></td><td className="mono-cell">{c.account}</td><td><span className="address-cell">{c.address}</span></td><td><Pill tone="blue">{c.plan}</Pill></td><td className="usage-cell">{c.usage.toLocaleString()} <small>kWh</small></td><td><StatusPill status={c.status}/></td><td><div className="row-actions"><button aria-label="View consumer" onClick={()=>view(c.id)}><ArrowUpRight size={15}/></button><button aria-label="Edit consumer" onClick={()=>edit(c.id)}><MoreHorizontal size={16}/></button><button aria-label="Delete consumer" onClick={()=>del(c.id)}><Trash2 size={14}/></button></div></td></tr>)}</DataTable>{visible.length===0&&<div className="empty-state"><Search size={23}/><b>No consumers found</b><p>Try adjusting the search or filters.</p></div>}<div className="table-footer"><span>Showing <b>{visible.length}</b> of <b>{rows.length===8?'1,248':rows.length}</b> consumers</span><div className="pagination"><button disabled aria-label="Previous page"><ChevronLeft size={15}/></button><button className="page-active">1</button><button>2</button><button>3</button><span>…</span><button>12</button><button aria-label="Next page"><ChevronRight size={15}/></button></div></div></div></div>
}

function MetersPage({rows,add,edit}:{rows:Meter[];add:()=>void;edit:(id:string)=>void}){
 const [q,setQ]=useState(''),[filter,setFilter]=useState('All statuses')
 const visible=rows.filter(m=>`${m.serial} ${m.consumer} ${m.zone}`.toLowerCase().includes(q.toLowerCase())&&(filter==='All statuses'||m.status===filter))
 return <div className="entity-page"><SectionHeading eyebrow="SMART METERING" title="Meters" subtitle="Track every connected meter, reading, and signal across your network." action={<button className="button-primary" onClick={add}><Plus size={16}/> Register meter</button>}/><div className="entity-summary-strip"><div><span className="summary-icon blue"><Gauge size={17}/></span><span><small>Total installed</small><b>1,248</b></span></div><div><span className="summary-icon green"><Wifi size={17}/></span><span><small>Online now</small><b>1,238</b></span><i className="summary-trend">99.2%</i></div><div><span className="summary-icon red"><RadioTower size={17}/></span><span><small>Needs attention</small><b>5</b></span></div><div><span className="summary-icon violet"><Zap size={17}/></span><span><small>Readings today</small><b>5,281</b></span></div></div><div className="meter-grid">{visible.map((m,i)=><div className="meter-card panel" key={m.id}><div className="meter-card-head"><span className="meter-id-icon"><Gauge size={18}/></span><StatusPill status={m.status}/><button aria-label="Edit meter" onClick={()=>edit(m.id)}><MoreHorizontal size={17}/></button></div><h3>{m.serial}</h3><p className="meter-customer">{m.consumer} <span>·</span> {m.zone}</p><div className="meter-reading"><span>Latest reading</span><b>{m.reading.toLocaleString()} <small>kWh</small></b></div><div className="meter-signal"><span>Signal strength</span><div className="signal-bars">{[1,2,3,4,5].map(n=><i key={n} className={m.signal>=n*20?'signal-on':''}/>)}</div><b>{m.signal||'—'}%</b></div><div className="meter-card-foot"><span><i className={m.status==='Online'?'live-dot':'muted-dot'}/>{m.status==='Online'?'Synced just now':m.status==='Offline'?'Last seen 2h ago':'Install scheduled'}</span><ArrowUpRight size={15}/></div><div className={`meter-card-glow meter-glow-${i%4}`}/></div>)}<button className="add-meter-card" onClick={add}><span><Plus size={19}/></span><b>Add a meter</b><small>Connect a smart meter to your network</small></button></div><div className="panel table-panel meter-table-panel"><PageToolbar><h3>All connected meters</h3><SearchControl value={q} onChange={setQ} placeholder="Search serial, consumer or zone"/><SelectControl value={filter} onChange={setFilter} options={['All statuses','Online','Offline','Installing']}/></PageToolbar><DataTable headers={['METER SERIAL','ASSIGNED CONSUMER','ZONE','LATEST READING','SIGNAL','STATUS','']} >{visible.map(m=><tr key={m.id}><td className="mono-cell">{m.serial}</td><td>{m.consumer}</td><td>{m.zone}</td><td className="usage-cell">{m.reading.toLocaleString()} <small>kWh</small></td><td><span className="signal-inline">{m.signal}%</span></td><td><StatusPill status={m.status}/></td><td><button className="plain-icon" onClick={()=>edit(m.id)} aria-label="Meter details"><ArrowUpRight size={15}/></button></td></tr>)}</DataTable></div></div>
}

function BillsPage({rows,generate,exportData}:{rows:Bill[];generate:()=>void;exportData:()=>void}){
 const [q,setQ]=useState(''),[filter,setFilter]=useState('All statuses')
 const visible=rows.filter(b=>`${b.id} ${b.consumer} ${b.account}`.toLowerCase().includes(q.toLowerCase())&&(filter==='All statuses'||b.status===filter))
 const total=rows.reduce((a,b)=>a+b.amount,0),due=rows.filter(b=>b.status!=='Paid').reduce((a,b)=>a+b.amount,0)
 return <div className="entity-page"><SectionHeading eyebrow="REVENUE & PAYMENTS" title="Billing" subtitle="Generate accurate bills, track payment status, and keep revenue moving." action={<button className="button-primary" onClick={generate}><Plus size={16}/> Generate bills</button>}/><div className="billing-hero"><div className="billing-hero-glow"/><div className="billing-hero-left"><span className="billing-icon"><Wallet size={19}/></span><span className="billing-label">SEPTEMBER 2025 · BILLING CYCLE</span><h2>{money(total)}</h2><span className="billing-subtitle">Total billing across all active accounts</span></div><div className="billing-hero-metrics"><div><small>Collected so far</small><b>{money(rows.filter(b=>b.status==='Paid').reduce((a,b)=>a+b.amount,0))}</b><span className="collection-progress"><i style={{width:'64%'}}/></span><span className="progress-caption">64% of cycle target</span></div><div><small>Outstanding balance</small><b>{money(due)}</b><span className="billing-alert"><i/> 3 payments need attention</span></div></div><div className="billing-hero-ring"><span>64%<small>COLLECTED</small></span></div></div><div className="entity-summary-strip"><div><span className="summary-icon blue"><FileText size={17}/></span><span><small>Bills generated</small><b>1,248</b></span></div><div><span className="summary-icon green"><Check size={17}/></span><span><small>Paid</small><b>1,012</b></span></div><div><span className="summary-icon amber"><Clock3 size={17}/></span><span><small>Pending</small><b>187</b></span></div><div><span className="summary-icon red"><CircleAlert size={17}/></span><span><small>Overdue</small><b>49</b></span></div></div><div className="panel table-panel"><PageToolbar><SearchControl value={q} onChange={setQ} placeholder="Search bills or customer"/><SelectControl value={filter} onChange={setFilter} options={['All statuses','Paid','Pending','Overdue']}/><button className="button-outline" onClick={exportData}><Download size={15}/> Export</button></PageToolbar><DataTable headers={['INVOICE','CONSUMER','BILLING PERIOD','USAGE','AMOUNT','DUE DATE','STATUS']} >{visible.map(b=><tr key={b.id}><td className="mono-cell">{b.id}</td><td><span className="table-consumer-name">{b.consumer}<small>{b.account}</small></span></td><td>{b.period}</td><td>{b.usage.toLocaleString()} kWh</td><td className="usage-cell">{money(b.amount)}</td><td>{b.due}</td><td><StatusPill status={b.status}/></td></tr>)}</DataTable><div className="table-footer"><span>Showing <b>{visible.length}</b> of <b>{rows.length}</b> invoices</span><div className="pagination"><button disabled><ChevronLeft size={15}/></button><button className="page-active">1</button><button>2</button><button>3</button><button><ChevronRight size={15}/></button></div></div></div></div>
}

function TechniciansPage({rows,add,edit}:{rows:Technician[];add:()=>void;edit:(id:string)=>void}){
 const [q,setQ]=useState(''),[filter,setFilter]=useState('All statuses')
 const visible=rows.filter(t=>`${t.name} ${t.zone}`.toLowerCase().includes(q.toLowerCase())&&(filter==='All statuses'||t.status===filter))
 return <div className="entity-page"><SectionHeading eyebrow="FIELD OPERATIONS" title="Technicians" subtitle="Coordinate your field team, assign zones, and track service work." action={<button className="button-primary" onClick={add}><Plus size={16}/> Add technician</button>}/><div className="field-hero"><div><span className="field-hero-icon"><Wrench size={19}/></span><span className="field-hero-label">FIELD TEAM STATUS</span><h2>Your people. <em>In motion.</em></h2><p>Live visibility into the crews keeping your network running.</p></div><div className="field-metric"><b>32</b><span>ACTIVE TECHNICIANS</span><i/> Across 8 service zones</div><div className="field-route"><span/><span/><span/><span/><span/></div></div><div className="entity-summary-strip"><div><span className="summary-icon green"><Check size={17}/></span><span><small>Available</small><b>18</b></span></div><div><span className="summary-icon blue"><Wrench size={17}/></span><span><small>On site</small><b>8</b></span></div><div><span className="summary-icon gray"><Clock3 size={17}/></span><span><small>Off duty</small><b>6</b></span></div><div><span className="summary-icon violet"><ClipboardList size={17}/></span><span><small>Jobs today</small><b>24</b></span></div></div><PageToolbar><SearchControl value={q} onChange={setQ} placeholder="Find a technician"/><SelectControl value={filter} onChange={setFilter} options={['All statuses','Available','On site','Off duty']}/><span className="toolbar-spacer"/><button className="button-outline" onClick={()=>window.alert('Zone assignments are shown in demo mode.')}> <MapPin size={15}/> Assign zones</button></PageToolbar><div className="technician-grid">{visible.map(t=><div className="technician-card panel" key={t.id}><div className="technician-card-head"><div className={`avatar avatar-${t.id.charCodeAt(2)%5}`}>{t.initials}</div><button className="plain-icon" aria-label="Technician options" onClick={()=>edit(t.id)}><MoreHorizontal size={18}/></button></div><h3>{t.name}</h3><p><MapPin size={13}/>{t.zone} service zone</p><div className="technician-card-meta"><span><ClipboardList size={14}/><b>{t.jobs}</b> jobs today</span><StatusPill status={t.status}/></div><button className="technician-view" onClick={()=>edit(t.id)}>View profile <ArrowUpRight size={14}/></button><div className="technician-accent"/></div>)}<button className="technician-add-card" onClick={add}><Plus size={20}/><b>Add a technician</b><span>Bring another member to your team</span></button></div><div className="panel service-panel"><div className="panel-head"><div><h3>Recent service activity</h3><p>Latest field updates across your zones</p></div><button className="panel-link compact">View service log <ArrowRight size={14}/></button></div>{[{name:'James Cooper',action:'Completed meter inspection',zone:'North End · MT-88421',time:'10:24 AM',status:'Completed'},{name:'Fatima Ali',action:'Customer connection check',zone:'Riverside · GF-2013',time:'09:48 AM',status:'In progress'},{name:'Daniel Kim',action:'Transformer maintenance',zone:'Midtown · SUB-008',time:'09:12 AM',status:'Scheduled'}].map((s,i)=><div className="service-row" key={s.name}><div className={`avatar avatar-${i}`}>{s.name.split(' ').map(x=>x[0]).join('')}</div><span className="service-detail"><b>{s.action}</b><small>{s.name} · {s.zone}</small></span><span className="service-time">{s.time}</span><StatusPill status={s.status}/></div>)}</div></div>
}

function ReportsPage({consumers,bills,meters,exportData}:{consumers:Consumer[];bills:Bill[];meters:Meter[];exportData:()=>void}){
 const [period,setPeriod]=useState('This year'),[kind,setKind]=useState('Energy usage'),[q,setQ]=useState('')
 const rows=consumers.filter(c=>`${c.name} ${c.zone} ${c.plan}`.toLowerCase().includes(q.toLowerCase()))
 return <div className="entity-page"><SectionHeading eyebrow="INSIGHTS & ANALYTICS" title="Reports" subtitle="Turn your operational data into a clearer view of what comes next." action={<button className="button-primary" onClick={exportData}><Download size={15}/> Export report</button>}/><div className="report-filters"><div className="report-filter-label"><SlidersHorizontal size={16}/><b>Report filters</b></div><label><small>DATE RANGE</small><SelectControl value={period} onChange={setPeriod} options={['This year','Last 12 months','This quarter','Last 30 days']}/></label><label><small>REPORT TYPE</small><SelectControl value={kind} onChange={setKind} options={['Energy usage','Collection summary','Consumer growth']}/></label><label><small>COMPARE WITH</small><SelectControl value="Previous period" onChange={()=>{}} options={['Previous period','Last year','No comparison']}/></label><button className="button-outline" onClick={()=>setQ('')}>Reset filters</button></div><div className="report-kpis">{[{name:'Energy consumed',value:'284.6 MWh',delta:'+12.8%',icon:Zap,color:'blue'},{name:'Revenue collected',value:money(bills.filter(b=>b.status==='Paid').reduce((a,b)=>a+b.amount,0)*87),delta:'+8.4%',icon:CircleDollarSign,color:'green'},{name:'Collection rate',value:'98.7%',delta:'+2.4%',icon:Wallet,color:'cyan'},{name:'Active consumers',value:consumers.length===8?'1,248':consumers.length.toLocaleString(),delta:'+8.2%',icon:Users,color:'violet'}].map(x=><div className="report-kpi panel" key={x.name}><span className={`report-kpi-icon ${x.color}`}><x.icon size={17}/></span><small>{x.name}</small><b>{x.value}</b><span className="stat-delta">↗ {x.delta} <i>vs previous period</i></span></div>)}</div><div className="report-chart-grid"><div className="panel report-chart-panel"><div className="panel-head"><div><h3>{kind} overview</h3><p>Monthly trend · {period}</p></div><button className="plain-icon"><MoreHorizontal size={17}/></button></div><div className="report-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={consumptionData} margin={{top:10,right:8,bottom:0,left:-15}}><defs><linearGradient id="reportFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#35b4d6" stopOpacity={.18}/><stop offset="100%" stopColor="#35b4d6" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#eef0f5" strokeDasharray="3 4" vertical={false}/><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fill:'#9298a8',fontSize:11}} dy={8}/><YAxis axisLine={false} tickLine={false} tick={{fill:'#9298a8',fontSize:11}}/><Tooltip/><Area dataKey="usage" type="monotone" stroke="#35b4d6" fill="url(#reportFill)" strokeWidth={2.5}/></AreaChart></ResponsiveContainer></div></div><div className="panel report-breakdown"><div className="panel-head"><div><h3>Network breakdown</h3><p>Current system snapshot</p></div></div><div className="breakdown-list"><div><span className="breakdown-dot blue"/><span>Consumers</span><b>{consumers.length===8?'1,248':consumers.length}</b></div><div><span className="breakdown-dot cyan"/><span>Online meters</span><b>{meters.filter(m=>m.status==='Online').length}</b></div><div><span className="breakdown-dot green"/><span>Paid bills</span><b>{bills.filter(b=>b.status==='Paid').length}</b></div><div><span className="breakdown-dot amber"/><span>Open service calls</span><b>18</b></div></div><div className="breakdown-footer"><span><i className="live-dot"/> LIVE DATA FEED</span><span>UPDATED JUST NOW</span></div></div></div><div className="panel table-panel report-table"><PageToolbar><h3>Consumer usage detail</h3><SearchControl value={q} onChange={setQ} placeholder="Search in this report"/><button className="button-outline" onClick={exportData}><Download size={14}/> CSV</button></PageToolbar><DataTable headers={['CONSUMER','ZONE','TARIFF','USAGE','ACCOUNT STATUS']}>{rows.slice(0,6).map(c=><tr key={c.id}><td>{c.name}</td><td>{c.zone}</td><td>{c.plan}</td><td>{c.usage} kWh</td><td><StatusPill status={c.status}/></td></tr>)}</DataTable></div></div>
}

function SettingsPage({demoMode,notify}:{demoMode:boolean;notify:(m:string)=>void}){
 const [tab,setTab]=useState('Organization'),[saved,setSaved]=useState(false)
 return <div className="entity-page"><SectionHeading eyebrow="PREFERENCES" title="Settings" subtitle="Manage your organization, account, and connected services."/><div className="settings-layout"><nav className="settings-nav">{['Organization','Profile','Notifications','Integrations','Security'].map((x,i)=><button key={x} className={tab===x?'settings-active':''} onClick={()=>setTab(x)}>{[Building2,UserRound,Bell,Layers3,Shield].map((I,j)=>j===i?<I key={x} size={17}/>:null)}{x}<ChevronRight size={15}/></button>)}</nav><div className="panel settings-panel"><div className="settings-panel-head"><div><h2>{tab} settings</h2><p>Update how your GridFlow workspace is configured.</p></div><Pill tone={demoMode?'amber':'green'} dot>{demoMode?'DEMO MODE':'CONNECTED'}</Pill></div>{tab==='Organization'?<><label className="settings-field"><span>Organization name</span><input defaultValue="Northstar Energy"/></label><label className="settings-field"><span>Primary service region</span><input defaultValue="San Francisco Bay Area"/></label><label className="settings-field"><span>Support email</span><input defaultValue="support@northstar.energy" type="email"/></label><div className="settings-divider"/><div className="integration-row"><span className="integration-logo"><Zap size={17}/></span><span><b>Supabase Auth</b><small>{demoMode?'Demo records are saved in this browser.':'Login is connected. Demo records remain in local browser storage.'}</small></span><Pill tone={demoMode?'amber':'green'} dot>{demoMode?'NOT CONFIGURED':'CONNECTED'}</Pill></div><div className="settings-help">For sign-in, add your Supabase project URL and anon key in <code>.env.local</code>. The included SQL schema defines the PostgreSQL tables; this demo currently keeps editable records in browser storage.</div></>:<><div className="settings-placeholder"><span className="settings-placeholder-icon">{tab==='Profile'?<UserRound/>:tab==='Notifications'?<Bell/>:tab==='Integrations'?<Layers3/>:<Shield/>}</span><b>{tab} preferences</b><p>Configure {tab.toLowerCase()} for the GridFlow workspace. These controls are available in demo mode.</p><label className="toggle-setting"><span>Email updates for important events</span><input type="checkbox" defaultChecked/><i/></label><label className="toggle-setting"><span>Weekly operations summary</span><input type="checkbox" defaultChecked/><i/></label></div></>}<div className="settings-actions"><button className="button-outline" onClick={()=>notify('Your changes were discarded.')}>Cancel</button><button className="button-primary" onClick={()=>{setSaved(true);notify('Settings saved successfully.');window.setTimeout(()=>setSaved(false),1800)}}>{saved?<Check size={16}/>:null}{saved?'Saved':'Save changes'}</button></div></div></div></div>
}

function EntityModal({modal,close,consumers,meters,bills,technicians,update,notify}:{modal:Modal;close:()=>void;consumers:Consumer[];meters:Meter[];bills:Bill[];technicians:Technician[];update:(key:'consumers'|'meters'|'bills'|'technicians',items:Consumer[]|Meter[]|Bill[]|Technician[])=>void;notify:(m:string,k?:'success'|'error')=>void}){
 const current=modal.id?consumers.find(x=>x.id===modal.id):undefined,isEdit=!!modal.id
 const [name,setName]=useState(current?.name||''),[account,setAccount]=useState(current?.account||''),[address,setAddress]=useState(current?.address||''),[zone,setZone]=useState(current?.zone||'North End'),[plan,setPlan]=useState(current?.plan||'Residential'),[email,setEmail]=useState(''),[phone,setPhone]=useState(''),[status,setStatus]=useState('Active'),[meterSerial,setMeterSerial]=useState(''),[consumer,setConsumer]=useState(consumers[0]?.name||''),[error,setError]=useState('')
 const title=modal.type==='consumer'?(isEdit?'Edit consumer':'Add consumer'):modal.type==='meter'?(isEdit?'Meter details':'Register meter'):modal.type==='technician'?(isEdit?'Technician profile':'Add technician'):modal.type==='bill'?'Generate bills':modal.type==='delete'?'Delete consumer':'Consumer details'
 const submit=(e:React.FormEvent)=>{e.preventDefault();setError('');if(modal.type==='consumer'){if(!name.trim()||!account.trim()||!address.trim()){setError('Name, account ID, and service address are required.');return}const item:Consumer={id:current?.id||`c-${Date.now()}`,name,account,address,zone,plan,usage:current?.usage||0,status:(status as Consumer['status'])};update('consumers',isEdit?consumers.map(x=>x.id===item.id?item:x):[item,...consumers]);notify(isEdit?'Consumer updated successfully.':'Consumer created successfully.')}else if(modal.type==='meter'){if(!meterSerial.trim()){setError('Meter serial number is required.');return}const old=meters.find(m=>m.id===modal.id);const item:Meter={id:old?.id||meterSerial,serial:meterSerial,consumer,zone,reading:old?.reading||0,status:'Online',signal:92};update('meters',old?meters.map(m=>m.id===old.id?item:m):[item,...meters]);notify(old?'Meter updated.':'Meter registered.')}else if(modal.type==='technician'){if(!name.trim()){setError('Technician name is required.');return}const item:Technician={id:`t-${Date.now()}`,name,initials:name.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase(),zone,jobs:0,status:'Available'};update('technicians',[item,...technicians]);notify('Technician added to the field team.')}else if(modal.type==='bill'){const newBills=consumers.map((c,i)=>({id:`INV-2026-${String(100+i).padStart(3,'0')}`,consumer:c.name,account:c.account,period:'October 2026',due:'Nov 14, 2026',amount:Math.round(c.usage*.225*100)/100,usage:c.usage,status:'Pending' as const}));update('bills',[...newBills,...bills]);notify(`${newBills.length} demo bills generated.`)}close()}
 const del=()=>{update('consumers',consumers.filter(c=>c.id!==modal.id));notify('Consumer deleted.');close()}
 return <motion.div className="modal-backdrop" initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><motion.div className="entity-modal" initial={{opacity:0,y:18,scale:.98}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0,y:12,scale:.98}} role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="modal-head"><div><span className="modal-eyebrow">GRIDFLOW OPERATIONS</span><h2 id="modal-title">{title}</h2></div><button className="icon-button" onClick={close} aria-label="Close dialog"><X size={18}/></button></div>
 {modal.type==='delete'?<div className="delete-content"><span className="delete-alert"><Trash2 size={21}/></span><p>Delete <b>{current?.name}</b> and remove their demo account record? This action cannot be undone.</p><div className="modal-actions"><button className="button-outline" onClick={close}>Cancel</button><button className="button-danger" onClick={del}><Trash2 size={15}/> Delete consumer</button></div></div>:modal.type==='details'?<div className="consumer-details"><div className="details-avatar">{current?.name.split(' ').map(x=>x[0]).join('')}</div><h3>{current?.name}</h3><Pill tone="green" dot>{current?.status}</Pill><div className="details-grid"><span>Account ID<b>{current?.account}</b></span><span>Service plan<b>{current?.plan}</b></span><span>Service zone<b>{current?.zone}</b></span><span>Monthly usage<b>{current?.usage} kWh</b></span><span>Address<b>{current?.address}</b></span><span>Meter ID<b>{meters.find(m=>m.consumer===current?.name)?.serial||'Pending assignment'}</b></span></div><div className="modal-actions"><button className="button-outline" onClick={close}>Close</button><button className="button-primary" onClick={()=>{close();notify('Consumer details are up to date.')}}>Done <Check size={15}/></button></div></div>:<form className="entity-form" onSubmit={submit}>
 {modal.type==='consumer'&&<><label>Full name<input value={name} onChange={e=>setName(e.target.value)} placeholder="e.g. Jordan Lee" autoFocus/></label><div className="form-two"><label>Account ID<input value={account} onChange={e=>setAccount(e.target.value)} placeholder="GF-2049"/></label><label>Plan<SelectControl value={plan} onChange={setPlan} options={['Residential','Business','Commercial']}/></label></div><label>Service address<input value={address} onChange={e=>setAddress(e.target.value)} placeholder="Street address, city"/></label><div className="form-two"><label>Service zone<SelectControl value={zone} onChange={setZone} options={['North End','Riverside','Midtown','Eastside']}/></label><label>Status<SelectControl value={status} onChange={setStatus} options={['Active','Pending','Suspended']}/></label></div><div className="form-two"><label>Email (optional)<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@example.com"/></label><label>Phone (optional)<input value={phone} onChange={e=>setPhone(e.target.value)} placeholder="+1 (555) 000-0000"/></label></div></>}
 {modal.type==='meter'&&<><label>Meter serial number<input value={meterSerial} onChange={e=>setMeterSerial(e.target.value)} placeholder="MT-88422" autoFocus/></label><label>Assign to consumer<SelectControl value={consumer} onChange={setConsumer} options={consumers.map(c=>c.name)}/></label><label>Service zone<SelectControl value={zone} onChange={setZone} options={['North End','Riverside','Midtown','Eastside']}/></label><div className="modal-note"><Wifi size={15}/> New meter will be added to the live demo network.</div></>}
 {modal.type==='technician'&&<><label>Full name<input value={name} onChange={e=>setName(e.target.value)} placeholder="e.g. Taylor Morgan" autoFocus/></label><label>Service zone<SelectControl value={zone} onChange={setZone} options={['North End','Riverside','Midtown','Eastside']}/></label><label>Work email<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@gridflow.demo"/></label><label>Phone<input value={phone} onChange={e=>setPhone(e.target.value)} placeholder="+1 (555) 000-0000"/></label></>}
 {modal.type==='bill'&&<><div className="bill-generate-summary"><span className="summary-icon blue"><FileText size={18}/></span><b>Generate October 2026 bills</b><span>{consumers.length} consumers</span></div><div className="bill-generate-options"><label><span>Billing period</span><b>October 2026</b></label><label><span>Due date</span><b>November 14, 2026</b></label><label><span>Calculation</span><b>Usage × current tariff</b></label></div><p className="modal-note">This creates sample pending bills for every consumer in your local demo workspace.</p></>}
 {error&&<div className="form-error"><CircleAlert size={14}/>{error}</div>}<div className="modal-actions"><button type="button" className="button-outline" onClick={close}>Cancel</button><button className="button-primary">{modal.type==='bill'?<><Zap size={15}/> Generate {consumers.length} bills</>:isEdit?'Save changes':modal.type==='consumer'?'Create consumer':modal.type==='meter'?'Register meter':'Add technician'}{modal.type!=='bill'&&<ArrowRight size={15}/>}</button></div></form>}</motion.div></motion.div>
}

function DataTable({headers,children}:{headers:string[];children:React.ReactNode}){return <div className="table-wrap"><table><thead><tr>{headers.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{children}</tbody></table></div>}
function StatusPill({status}:{status:string}){const map:Record<string,string>={Active:'green',Paid:'green',Online:'green',Available:'green',Completed:'green',Pending:'amber','On site':'blue','In progress':'blue',Offline:'red',Overdue:'red',Suspended:'red',Installing:'violet','Off duty':'gray',Scheduled:'amber'};return <Pill tone={map[status]||'gray'} dot>{status}</Pill>}
function exportRows(rows:unknown[],filename:string){const list=rows as Record<string,unknown>[],keys=Object.keys(list[0]||{}),quote=(v:unknown)=>`"${String(v??'').replaceAll('"','""')}"`,csv=[keys.join(','),...list.map(r=>keys.map(k=>quote(r[k])).join(','))].join('\r\n'),blob=new Blob([csv],{type:'text/csv'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url)}
